<!-- 业务处理工作台：两步表单、受控附件初稿分析与推荐方案协作区。 -->
<template>
  <section class="task-workbench">
    <div class="page-heading"><h2>业务处理向导</h2><el-tag v-if="task">{{ taskStatusLabel }}</el-tag></div>
    <el-alert v-if="errorMessage" :title="errorMessage" type="error" :closable="false" show-icon />
    <el-row :gutter="20"><el-col :span="16"><el-card shadow="never" class="form-card guided-workflow">
      <el-steps :active="activeStep" simple><el-step title="业务说明" /><el-step title="模型协作与确认" /></el-steps>
      <el-form v-if="activeStep === 0" :model="form" label-position="top" class="task-form">
        <el-form-item label="业务标题"><el-input v-model.trim="form.title" /></el-form-item>
        <el-form-item label="业务说明"><el-input v-model.trim="form.question" type="textarea" :rows="6" /></el-form-item>
        <el-form-item label="附件材料（可选）"><el-upload action="#" :auto-upload="false" :file-list="attachmentFiles" :on-change="selectAttachment" :on-remove="removeAttachment" accept=".txt,.md,.csv,.json" multiple><el-button type="primary" plain>选择附件</el-button></el-upload><p class="attachment-note">最多 3 个附件，单个不超过 1 MB，支持 txt、md、csv、json 格式。</p></el-form-item>
        <el-button type="primary" :loading="saving" @click="createTaskDraft">开始模型分析</el-button>
      </el-form>
      <template v-else><div class="handling-workspace"><section class="handling-form-panel">
        <h4>对象与处理范围</h4><p v-if="modelLoading">模型正在整理初稿，请稍候。</p>
        <el-form v-else :model="form" label-position="top" class="task-form">
          <el-form-item label="处理方式"><el-radio-group v-model="form.handlingType"><el-radio label="INVESTIGATE">业务调查</el-radio><el-radio label="ADJUST">业务调整</el-radio></el-radio-group></el-form-item>
          <el-form-item label="业务场景"><el-select v-model="form.premiseType"><el-option label="业务调整" value="业务调整" /><el-option label="人员离任或岗位变更" value="人员变更" /><el-option label="审批流程异常" value="审批异常" /><el-option label="权限或配置调整" value="配置调整" /></el-select></el-form-item>
          <el-form-item label="处理对象"><el-input v-model.trim="form.subjectKey" /></el-form-item><el-form-item label="已知情况"><el-input v-model.trim="form.statement" type="textarea" :rows="3" /></el-form-item><el-form-item label="信息来源"><el-input v-model.trim="form.sourceDescription" /></el-form-item><el-form-item label="处理系统"><el-select v-model="form.systemCode"><el-option label="财务共享合成验证系统" value="FIN-SYN" /></el-select></el-form-item>
          <el-row :gutter="16"><el-col :span="12"><el-form-item label="开始日期"><el-input v-model.trim="form.startDate" /></el-form-item></el-col><el-col :span="12"><el-form-item label="结束日期"><el-input v-model.trim="form.endDate" /></el-form-item></el-col></el-row>
          <el-form-item label="处理内容"><el-checkbox-group v-model="form.investigationAreas"><el-checkbox label="APPROVAL">审批流程</el-checkbox><el-checkbox label="ROLE">角色权限</el-checkbox><el-checkbox label="ACCOUNTING">会计配置</el-checkbox><el-checkbox label="CONFIG">系统配置引用</el-checkbox></el-checkbox-group></el-form-item>
        </el-form>
      </section><section class="model-conversation plan-editor"><div class="card-heading"><h4>推荐业务方案</h4><el-tag v-if="proposal" type="success">已生成</el-tag></div><p v-if="guidance" class="model-reason">{{ guidance.draft.reason }}</p><el-button v-if="!guidance && !modelLoading" type="primary" @click="requestGuidance">重新开始模型分析</el-button><el-input v-model.trim="recommendedGoal" type="textarea" :rows="4" /><h4>模型协助修改</h4><div class="chat-history"><article v-for="message in chatMessages" :key="message.id" class="chat-message" :class="`chat-message--${message.role}`"><strong>{{ message.role === 'operator' ? '管理员' : '模型' }}</strong><p>{{ message.content }}</p></article></div><el-input v-model.trim="chatMessage" type="textarea" :rows="3" :disabled="!guidance || chatLoading" placeholder="直接说明希望如何修改推荐方案" /><div class="chat-actions"><el-button type="primary" :loading="chatLoading" :disabled="!guidance || !chatMessage" @click="reviseGuidance">发送修改意见</el-button><el-button v-if="proposal" :loading="saving" :disabled="!planChanged" @click="saveRevisedPlan">保存修改后的方案</el-button></div><el-button v-if="!proposal" type="primary" :loading="saving" @click="generateBusinessPlan">生成业务方案</el-button></section></div><div v-if="proposal" class="next-action-panel business-plan-result"><strong>业务方案已生成</strong></div></template>
    </el-card></el-col><el-col :span="8"><el-card shadow="never" class="detail-card journey-card"><div class="card-heading"><h3>业务处理概览</h3><span v-if="task">{{ taskStatusLabel }}</span></div><div v-if="!task" class="empty-state">等待创建业务处理</div><template v-else><dl class="task-summary"><dt>业务标题</dt><dd>{{ task.title }}</dd><dt>处理对象</dt><dd>{{ form.subjectKey || '待模型分析' }}</dd><dt>处理内容</dt><dd>{{ areaLabels }}</dd></dl><el-collapse class="technical-details"><el-collapse-item title="技术明细"><dl class="task-summary"><dt>模型</dt><dd>{{ guidance?.metadata.modelName || '尚未调用' }}</dd><dt>模式</dt><dd>{{ guidance?.metadata.mode || '—' }}</dd><dt>调用耗时</dt><dd>{{ guidance ? `${guidance.metadata.latencyMillis} 毫秒` : '—' }}</dd><dt>Token 数</dt><dd>{{ guidance?.metadata.tokens ?? '—' }}</dd><template v-if="guidance?.metadata.reasoningEffort"><dt>推理强度</dt><dd>{{ guidance.metadata.reasoningEffort }}</dd></template></dl></el-collapse-item></el-collapse></template></el-card></el-col></el-row>
  </section>
</template>
<script lang="ts">
import Vue from 'vue'
import { StepProposalResponse, TaskResponse } from '../api/generated'
import { buildScopePayload, DEFAULT_RUNTIME_BUNDLE_ID } from '../services/business-workflow'
import { proposeSteps, reviseStepProposal } from '../services/execution-api'
import { getCurrentIdentity } from '../services/identity'
import { BusinessGuidanceResponse, generateBusinessGuidance, reviseBusinessGuidance } from '../services/model-api'
import { addPremise, confirmScope, createTask, isStaleError } from '../services/task-api'
interface Form { title: string; question: string; handlingType: 'INVESTIGATE' | 'ADJUST'; premiseType: string; subjectKey: string; statement: string; sourceDescription: string; systemCode: 'FIN-SYN'; startDate: string; endDate: string; investigationAreas: Array<'APPROVAL' | 'ROLE' | 'ACCOUNTING' | 'CONFIG'>; dataUse: 'MINIMUM' }
interface Chat { id: string; role: 'operator' | 'model'; content: string }
interface AttachmentFile { name: string; size?: number; raw?: File }
const AREAS: Record<string, string> = { APPROVAL: '审批流程', ROLE: '角色权限', ACCOUNTING: '会计配置', CONFIG: '系统配置引用' }
const ATTACHMENT_EXTENSIONS = ['txt', 'md', 'csv', 'json']
/** 生成每次新建业务处理所需的独立默认表单，避免复用上一份草稿引用。 */
const createInitialForm = (): Form => ({ title: '', question: '', handlingType: 'INVESTIGATE', premiseType: '人员变更', subjectKey: '', statement: '', sourceDescription: '', systemCode: 'FIN-SYN', startDate: '2026-01-01', endDate: '2026-12-31', investigationAreas: ['APPROVAL'], dataUse: 'MINIMUM' })
/** 仅接受后端可受控分析的文本附件，避免浏览器选择无效格式。 */
const isSupportedAttachment = (file: AttachmentFile): boolean => { const extension = file.name.split('.').pop()?.toLowerCase(); return Boolean(file.raw) && file.size !== 0 && file.size !== undefined && file.size <= 1024 * 1024 && Boolean(extension && ATTACHMENT_EXTENSIONS.includes(extension)) }
export default Vue.extend({ name: 'WorkbenchHome', data() { return { activeStep: 0, saving: false, modelLoading: false, chatLoading: false, task: null as TaskResponse | null, guidance: null as BusinessGuidanceResponse | null, proposal: null as StepProposalResponse | null, recommendedGoal: '', planChanged: false, chatMessage: '', chatMessages: [] as Chat[], attachmentFiles: [] as AttachmentFile[], errorMessage: '', form: createInitialForm() } }, computed: {
  /** 返回当前任务的业务处理状态文案。 */ taskStatusLabel(): string { return this.proposal ? '业务方案已生成' : this.task ? '处理中' : '未开始' },
  /** 将已选处理内容转换为概览中的中文标签。 */ areaLabels(): string { return this.form.investigationAreas.map(x => AREAS[x]).filter(Boolean).join('、') || '待模型分析' },
}, watch: { /** 仅响应显式新建入口的草稿标识，普通导航继续保留当前向导状态。 */ '$route.query.draft'(): void { this.resetDraft() } }, methods: {
  /** 在无进行中写请求时清空本地草稿和待分析附件，不删除已创建的后端任务。 */ resetDraft(): void { if (this.saving || this.modelLoading || this.chatLoading) return; this.activeStep = 0; this.task = null; this.guidance = null; this.proposal = null; this.recommendedGoal = ''; this.planChanged = false; this.chatMessage = ''; this.chatMessages = []; this.attachmentFiles = []; this.errorMessage = ''; this.form = createInitialForm() },
  /** 校验并保存当前选择的本地附件，不在浏览器读取附件正文。 */ selectAttachment(file: AttachmentFile, fileList: AttachmentFile[]): void { if (!isSupportedAttachment(file)) { this.errorMessage = '附件需为非空的 txt、md、csv、json 文件，且单个不超过 1 MB'; this.attachmentFiles = fileList.filter(item => item !== file); return } if (fileList.length > 3) { this.errorMessage = '最多可选择 3 个附件'; this.attachmentFiles = fileList.filter(item => item !== file); return } this.errorMessage = ''; this.attachmentFiles = fileList },
  /** 同步移除待分析附件，已创建的任务和模型草稿不受影响。 */ removeAttachment(file: AttachmentFile, fileList: AttachmentFile[]): void { this.attachmentFiles = fileList },
  /** 创建任务后请求模型初稿；附件仅在本次初稿调用中提交。 */ async createTaskDraft(): Promise<void> { const identity = getCurrentIdentity(); if (!identity || !this.form.title || !this.form.question) { this.errorMessage = '请填写业务标题和业务说明'; return } await this.execute(async () => { this.task = await createTask({ title: this.form.title, originalQuestion: this.form.question, initiatorUserId: identity.userId, runtimeBundleId: DEFAULT_RUNTIME_BUNDLE_ID }); this.activeStep = 1 }); await this.requestGuidance() },
  /** 发送当前任务与受控本地附件以获取可编辑初稿，失败时保留附件供重试。 */ async requestGuidance(): Promise<void> { if (!this.task) return; this.modelLoading = true; try { const response = await generateBusinessGuidance(this.task.taskId, this.attachmentFiles.map(file => file.raw).filter((file): file is File => Boolean(file))); this.applyGuidance(response); this.chatMessages = [{ id: `m-${Date.now()}`, role: 'model', content: response.reply }] } catch (error: unknown) { this.errorMessage = error instanceof Error ? error.message : '模型暂时无法生成初稿' } finally { this.modelLoading = false } },
  /** 向模型发送管理员修改意见并以返回草稿更新界面。 */ async reviseGuidance(): Promise<void> { if (!this.task || !this.guidance || !this.chatMessage.trim()) return; const message = this.chatMessage.trim(); this.chatLoading = true; this.chatMessage = ''; this.chatMessages.push({ id: `o-${Date.now()}`, role: 'operator', content: message }); try { const response = await reviseBusinessGuidance(this.task.taskId, message, this.guidance.draft); this.applyGuidance(response); this.planChanged = Boolean(this.proposal); this.chatMessages.push({ id: `m-${Date.now()}`, role: 'model', content: response.reply }) } catch (error: unknown) { this.errorMessage = error instanceof Error ? error.message : '模型暂时无法修改方案' } finally { this.chatLoading = false } },
  /** 将受控模型初稿回填为可由管理员继续调整的业务表单。 */ applyGuidance(response: BusinessGuidanceResponse): void { const draft = response.draft; this.guidance = response; this.form.handlingType = draft.handlingType; this.form.premiseType = draft.premiseType; this.form.subjectKey = draft.objectKey || draft.subjectKey; this.form.statement = draft.statement; this.form.sourceDescription = draft.sourceDescription; this.form.systemCode = draft.systemCode; this.form.startDate = draft.startDate; this.form.endDate = draft.endDate; this.form.investigationAreas = draft.investigationAreas; this.recommendedGoal = draft.recommendedGoal },
  /** 在管理员补全对象、依据和推荐方案后写入权威前提、范围和步骤提议。 */ async generateBusinessPlan(): Promise<void> { if (!this.task || !this.guidance || !this.form.subjectKey || !this.form.statement || !this.form.sourceDescription || !this.recommendedGoal.trim()) { this.errorMessage = '请补全处理对象、信息依据和推荐方案'; return } await this.execute(async () => { this.task = await addPremise(this.task!.taskId, { premiseType: this.form.premiseType, subjectKey: this.form.subjectKey, statement: this.form.statement, sourceDescription: this.form.sourceDescription }, this.task!.rowVersion); this.task = await confirmScope(this.task!.taskId, buildScopePayload({ systemCode: this.form.systemCode, objectKey: this.form.subjectKey, dateRange: [this.form.startDate, this.form.endDate], investigationAreas: this.form.investigationAreas, dataUse: this.form.dataUse }), this.task!.rowVersion); this.proposal = await proposeSteps(this.task!.taskId, { steps: [{ goal: this.recommendedGoal.trim(), recommended: true }] }, this.task!.rowVersion) }) },
  /** 将管理员确认后的推荐方案修改同步到当前步骤提议。 */ async saveRevisedPlan(): Promise<void> { if (!this.task || !this.proposal || !this.recommendedGoal.trim()) return; await this.execute(async () => { const revised = await reviseStepProposal(this.task!.taskId, this.proposal!.currentStepId, this.recommendedGoal.trim()); this.proposal = { ...this.proposal!, steps: this.proposal!.steps.map(step => step.stepId === revised.stepId ? revised : step) }; this.planChanged = false }) },
  /** 串行执行任务写操作并将可识别异常转换为页面错误文案。 */ async execute(action: () => Promise<void>): Promise<void> { if (this.saving) return; this.saving = true; this.errorMessage = ''; try { await action() } catch (error: unknown) { this.errorMessage = isStaleError(error) ? '当前范围已发生变化，请刷新后重新确认' : error instanceof Error ? error.message : '请求未完成，请稍后重试' } finally { this.saving = false } },
} })
</script>
<style scoped>
.attachment-note { margin: 8px 0 0; color: #606266; font-size: 14px; }
</style>
